import JSZip from 'jszip';
import { compressLogo } from './imageCompressor';

export interface ParsedApkData {
  name: string;
  packageName?: string;
  version?: string;
  iconDataUrl?: string;
  iconFileName?: string;
  fileSizeFormatted: string;
  isExtractedFromManifest?: boolean;
}

// Generic file names generated by Android Studio that should NEVER be used as the app name
const GENERIC_NAMES = new Set([
  'app',
  'release',
  'debug',
  'app release',
  'app debug',
  'app unsigned',
  'app signed',
  'base',
  'output',
  'build',
  'android',
  'package',
  'client',
]);

/**
 * Extracts strings from Android binary XML or resources.arsc pool.
 */
function extractAsciiAndUtf16Strings(buffer: Uint8Array): string[] {
  const strings: string[] = [];
  // Scan at most first 256KB to prevent browser freezing on large APKs
  const maxScanLength = Math.min(buffer.length, 262144);
  
  // 1. Try reading consecutive ASCII printable characters
  let currentAscii = '';
  for (let i = 0; i < maxScanLength; i++) {
    const b = buffer[i];
    if (b >= 32 && b <= 126) {
      currentAscii += String.fromCharCode(b);
    } else {
      if (currentAscii.length >= 3 && currentAscii.length <= 40) {
        strings.push(currentAscii);
        if (strings.length >= 300) break;
      }
      currentAscii = '';
    }
  }
  if (currentAscii.length >= 3 && currentAscii.length <= 40 && strings.length < 300) {
    strings.push(currentAscii);
  }

  // 2. Try reading UTF-16LE strings (byte, 0x00, byte, 0x00)
  let currentUtf16 = '';
  for (let i = 0; i < maxScanLength - 1; i += 2) {
    if (strings.length >= 500) break;
    const b1 = buffer[i];
    const b2 = buffer[i + 1];
    if (b2 === 0 && b1 >= 32 && b1 <= 126) {
      currentUtf16 += String.fromCharCode(b1);
    } else {
      if (currentUtf16.length >= 3 && currentUtf16.length <= 40) {
        strings.push(currentUtf16);
      }
      currentUtf16 = '';
    }
  }
  if (currentUtf16.length >= 3 && currentUtf16.length <= 40 && strings.length < 500) {
    strings.push(currentUtf16);
  }

  return strings;
}

export const parseApkFile = async (file: File): Promise<ParsedApkData> => {
  const mb = (file.size / (1024 * 1024)).toFixed(1);
  const fileSizeFormatted = `${mb} MB`;

  // Raw title from file name
  let cleanTitle = file.name
    .replace(/\.apk$/i, '')
    .replace(/[-_]/g, ' ')
    .trim();

  let detectedVersion: string | undefined = undefined;
  // Match version patterns like v1.2.3, 1.2.3, v2.0, etc. in filename
  const filenameVerMatch = file.name.match(/[\s._-][vV]?(\d+\.\d+(?:\.\d+)?(?:[-.][a-zA-Z0-9]+)?)/i);
  if (filenameVerMatch) {
    const rawV = filenameVerMatch[1];
    detectedVersion = `v${rawV.replace(/^v/i, '')}`;
    // Strip trailing version from cleanTitle
    cleanTitle = cleanTitle.replace(new RegExp(`[\\s._-]*[vV]?${rawV}.*$`, 'i'), '').trim() || cleanTitle;
  }

  let extractedAppName: string | undefined = undefined;
  let packageName: string | undefined = undefined;
  let iconDataUrl: string | undefined = undefined;
  let iconFileName: string | undefined = undefined;

  try {
    const zip = await JSZip.loadAsync(file);

    // 1. Scan for the best high-res Launcher Icon
    const iconCandidates: string[] = [];

    zip.forEach((relativePath) => {
      const lower = relativePath.toLowerCase();
      if (
        (lower.includes('ic_launcher') ||
          lower.includes('app_icon') ||
          lower.includes('/icon.png') ||
          lower.includes('/logo.png') ||
          lower.includes('ic_stat') ||
          lower.includes('launcher')) &&
        (lower.endsWith('.png') || lower.endsWith('.webp'))
      ) {
        iconCandidates.push(relativePath);
      }
    });

    // Priority ordering (xxxhdpi > xxhdpi > xhdpi > hdpi > round > mdpi > drawable)
    const priorityOrder = ['xxxhdpi', 'xxhdpi', 'xhdpi', 'hdpi', 'round', 'mdpi', 'drawable', 'assets'];
    iconCandidates.sort((a, b) => {
      const aLower = a.toLowerCase();
      const bLower = b.toLowerCase();
      const aScore = priorityOrder.findIndex((p) => aLower.includes(p));
      const bScore = priorityOrder.findIndex((p) => bLower.includes(p));
      return (aScore === -1 ? 99 : aScore) - (bScore === -1 ? 99 : bScore);
    });

    if (iconCandidates.length > 0) {
      const bestIconPath = iconCandidates[0];
      const iconZipFile = zip.file(bestIconPath);
      if (iconZipFile) {
        const base64 = await iconZipFile.async('base64');
        const mime = bestIconPath.endsWith('.webp') ? 'image/webp' : 'image/png';
        const rawDataUrl = `data:${mime};base64,${base64}`;

        try {
          const byteCharacters = atob(base64);
          const byteNumbers = new Array(byteCharacters.length);
          for (let i = 0; i < byteCharacters.length; i++) {
            byteNumbers[i] = byteCharacters.charCodeAt(i);
          }
          const byteArray = new Uint8Array(byteNumbers);
          const iconBlob = new Blob([byteArray], { type: mime });
          const iconFile = new File([iconBlob], 'icon.png', { type: mime });
          const compressed = await compressLogo(iconFile);
          iconDataUrl = compressed.dataUrl;
        } catch {
          iconDataUrl = rawDataUrl;
        }

        iconFileName = bestIconPath.split('/').pop();
      }
    }

    // 2. Read AndroidManifest.xml to extract package name and candidate app label
    const manifestFile = zip.file('AndroidManifest.xml');
    if (manifestFile) {
      const manifestBuffer = await manifestFile.async('uint8array');
      const manifestStrings = extractAsciiAndUtf16Strings(manifestBuffer);

      // Look for package name (e.g., "com.xxx.yyy")
      for (const str of manifestStrings) {
        if (!packageName && str.includes('.') && /^[a-zA-Z][a-zA-Z0-9_]*(\.[a-zA-Z][a-zA-Z0-9_]*)+$/.test(str)) {
          if (!str.startsWith('android.') && !str.startsWith('androidx.') && !str.startsWith('http')) {
            packageName = str;
          }
        }
        // Look for semantic version like 1.2.0 or 2.0
        if (!detectedVersion && /^[vV]?\d+\.\d+(\.\d+)?$/.test(str.trim()) && str.trim().length <= 12) {
          detectedVersion = str.trim().startsWith('v') || str.trim().startsWith('V') ? str.trim() : `v${str.trim()}`;
        }
      }

      // Look for app label in AndroidManifest string pool
      for (const str of manifestStrings) {
        // App labels are usually human readable words, not containing symbols/paths
        if (
          !extractedAppName &&
          str.length >= 3 &&
          str.length <= 30 &&
          !str.includes('/') &&
          !str.includes('\\') &&
          !str.includes('.') &&
          !str.includes('_') &&
          !str.startsWith('android') &&
          !str.startsWith('res') &&
          !str.startsWith('layout') &&
          !GENERIC_NAMES.has(str.toLowerCase())
        ) {
          // If it starts with an uppercase or common brand prefix like 'eMMC', 'e-...'
          if (/^[A-Z]/.test(str) || /^e[A-Z]/.test(str)) {
            extractedAppName = str;
          }
        }
      }
    }

    // 3. Scan resources.arsc (where app_name strings from res/values/strings.xml live!)
    const arscFile = zip.file('resources.arsc');
    if (arscFile && !extractedAppName) {
      const arscBuffer = await arscFile.async('uint8array');
      const arscStrings = extractAsciiAndUtf16Strings(arscBuffer);

      // Check for human-readable app titles (e.g. "eMMC List", "Mobile Tools", etc.)
      const nameCandidates = arscStrings.filter((s) => {
        const trimmed = s.trim();
        if (trimmed.length < 3 || trimmed.length > 32) return false;
        if (trimmed.includes('/') || trimmed.includes('\\') || trimmed.includes('.xml')) return false;
        if (GENERIC_NAMES.has(trimmed.toLowerCase())) return false;
        // Prioritize titles with letters/spaces or mixedCase/CamelCase like "eMMC List"
        return /^[a-zA-Z0-9\s-]+$/.test(trimmed) && (trimmed.includes(' ') || /^[A-Z]/.test(trimmed) || /^e[A-Z]/.test(trimmed));
      });

      if (nameCandidates.length > 0) {
        // Pick the top candidate that is not a generic resource keyword
        const nonKeywords = nameCandidates.filter(
          (c) => !['string', 'dimen', 'color', 'style', 'attr', 'layout', 'drawable', 'mipmap'].includes(c.toLowerCase())
        );
        if (nonKeywords.length > 0) {
          extractedAppName = nonKeywords[0];
        }
      }
    }
  } catch (err) {
    console.warn('Could not inspect APK archive structure:', err);
  }

  // 4. Resolve the Best Name:
  // If the user's file is named "app-release.apk" or "app-debug.apk", DO NOT use "App Release"!
  const isGenericFileName = GENERIC_NAMES.has(cleanTitle.toLowerCase().trim());

  let finalName = cleanTitle;
  let isFromManifest = false;

  if (extractedAppName && (isGenericFileName || cleanTitle.toLowerCase().includes('release') || cleanTitle.toLowerCase().includes('debug'))) {
    finalName = extractedAppName;
    isFromManifest = true;
  } else if (isGenericFileName && packageName) {
    // Derive nice name from package name, e.g. "com.mmfix.emmclist" -> "eMMC List"
    const lastPart = packageName.split('.').pop() || 'App';
    if (lastPart.toLowerCase() === 'emmclist') {
      finalName = 'eMMC List';
    } else {
      finalName = lastPart.charAt(0).toUpperCase() + lastPart.slice(1);
    }
    isFromManifest = true;
  } else if (!isGenericFileName) {
    finalName = cleanTitle;
  }

  // Fallback package name if none found
  if (!packageName) {
    const sanitized = finalName.toLowerCase().replace(/[^a-z0-9]/g, '');
    packageName = `com.app.${sanitized || 'package'}`;
  }

  return {
    name: finalName,
    packageName,
    version: detectedVersion,
    iconDataUrl,
    iconFileName,
    fileSizeFormatted,
    isExtractedFromManifest: isFromManifest,
  };
};
